<script lang="ts">
 import { onMount } from 'svelte';
 import {EXPEDITIONS,initial,place,routes,walk,sketch,rest,moveReason,sketchReason,restReason,shelterFree,score,stars,solve,type State} from './engine';
 let selected=$state(0);let expedition=$derived(EXPEDITIONS[selected]);let game=$state<State>(initial(EXPEDITIONS[0]));let history=$state<State[]>([]);let records=$state<number[]>([0,0,0,0]);let modal=$state<'intro'|'help'|null>('intro');let hint=$state('');let dialog=$state<HTMLDivElement>();
 const current=$derived(place(expedition,game.at));const paths=$derived(routes(expedition,game));const completed=$derived(expedition.required.filter(id=>game.sketches.includes(id)).length);const used=$derived(expedition.daylight-game.light);
 function commit(next:State){if(next===game)return;history=[...history,game];game=next;hint='';if(next.status==='won'){records=records.map((v,i)=>i===selected?Math.max(v,stars(expedition,next)):v);try{localStorage.setItem('funapps-rockies-record-v1',JSON.stringify(records))}catch{}}}
 function go(id:string){commit(walk(expedition,game,id))}
 function choose(i:number){selected=i;game=initial(EXPEDITIONS[i]);history=[];hint=''}
 function undo(){const previous=history.at(-1);if(previous){game=previous;history=history.slice(0,-1);hint=''}}
 function showHint(){const answer=solve(expedition,game);const a=answer?.[0];hint=!answer?'No complete route remains from here. Undo a move or start this hike again.':!a?'The sketchbook is safely home.':a.kind==='walk'?`One possible next step: walk to ${place(expedition,a.to).name}.`:a.kind==='sketch'?'One possible next step: sketch this view.':'One possible next step: take a break and recover energy.';}
 function modalKeys(event:KeyboardEvent){if(event.key==='Escape'){modal=null;return}if(event.key!=='Tab')return;const focusable=Array.from(dialog?.querySelectorAll<HTMLButtonElement>('button:not([disabled]),a[href]')||[]);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
 $effect(()=>{if(modal&&dialog)dialog.querySelector<HTMLButtonElement>('button')?.focus()});
 onMount(()=>{try{const data=JSON.parse(localStorage.getItem('funapps-rockies-record-v1')||'null');if(Array.isArray(data)&&data.length===4&&data.every(n=>Number.isInteger(n)&&n>=0&&n<=3))records=data}catch{}});
 function trailClass(a:string,b:string){const taken=game.path.some((n,i)=>i>0&&((n===a&&game.path[i-1]===b)||(n===b&&game.path[i-1]===a)));return taken?'taken':a===game.at||b===game.at?'available':''}
</script>

<svelte:head><title>Westward: A Maritimer in the Rockies | FunApps</title></svelte:head>
<div class="page" inert={modal!==null}>
 <header class="masthead"><a href="https://funapps.ca" class="brand"><span>f.</span> FUNAPPS <small>/ FROM AWAY</small></a><div class="header-right"><a href="?" class="text-button">Quick play</a><span>ALBERTA · CANADIAN ROCKIES</span><button class="text-button" onclick={()=>modal='help'}>How to explore</button></div></header>
 <main>
  <section class="intro-heading"><div><p class="eyebrow">A MARITIMER, A SKETCHBOOK, A VERY BIG HORIZON.</p><h1>Westward<span>.</span></h1><p class="subtitle">A little farther from the ocean. A little closer to the sky.</p></div><div class="traveller-note"><span>POSTMARK / HOME</span><p>“These are some<br><em>serious hills.”</em></p><small>FIELD NOTES FROM THE ROCKIES</small></div></section>
  <nav class="expeditions" aria-label="Choose an expedition">{#each EXPEDITIONS as e,i}<button class:chosen={i===selected} aria-pressed={i===selected} onclick={()=>choose(i)}><span class="tab-region">{e.region}</span><strong>{e.name}</strong><span class="tab-stars" aria-label={`${records[i]} of 3 trail badges`}>{'◆'.repeat(records[i])}{'◇'.repeat(3-records[i])}</span></button>{/each}</nav>
  <p class="switch-note">Choose any expedition. Switching starts a fresh hike; earned badges stay with you.</p>
  <section class="supplies" aria-label="Hiking supplies"><div><span>DAYLIGHT LEFT</span><strong>{game.light}<small>/ {expedition.daylight}</small></strong><meter min="0" max={expedition.daylight} value={game.light} aria-label="Daylight remaining"></meter></div><div><span>TRAIL ENERGY</span><strong>{game.energy}<small>/ 12</small></strong><meter min="0" max="12" value={game.energy} aria-label="Energy remaining"></meter></div><div><span>TEA RATIONS</span><strong>{game.tea}<small>packed breaks</small></strong></div><div><span>LOOKOUT SKETCHES</span><strong>{completed}<small>/ {expedition.required.length}</small></strong></div></section>
  <div class="game-layout">
   <section class="atlas" aria-label="Mountain trail map">
    <div class="map-heading"><div><p class="eyebrow">YOUR LITTLE ALPINE ATLAS</p><h2>{current.name}<small> · Elevation band {current.height}</small></h2></div><span class="map-tag">{expedition.region}</span></div>
    <div class="map-scroll"><div class="map-frame">
     <svg viewBox="0 0 880 560" role="img" aria-label="Illustrated mountain trail network. Dotted paths connect stops; gold paths show your journey. All travel is available using the route buttons.">
      <defs><pattern id="mapgrid" width="44" height="40" patternUnits="userSpaceOnUse"><path d="M44 0H0V40" fill="none" stroke="#597f7b" stroke-width=".7" opacity=".12"/></pattern><pattern id="snow" width="8" height="8" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="#78939b" opacity=".2"/></pattern><linearGradient id="terrain" x2="0" y2="1"><stop stop-color="#d8e5e5"/><stop offset="1" stop-color="#c7d8c5"/></linearGradient></defs>
      <rect width="880" height="560" fill="url(#terrain)"/><rect width="880" height="560" fill="url(#mapgrid)"/>
      <path class="contour" d="M-50 405Q110 340 150 205T370 28 600 36 970 170M-40 375Q100 315 120 192T367 0 623 10 970 140M-20 440Q130 355 180 235T380 60 620 60 970 215M-40 475Q180 395 220 270T435 99 650 109 970 255M-20 510Q220 450 270 310T470 145 690 145 970 300M-10 545Q260 480 320 355T520 190 725 195 970 350"/>
      <path d="M332 380q68-35 127-4t35 72q-16 30-94 23t-100-29q-21-25 32-62" fill="#80b8be" stroke="#d9e8df" stroke-width="7"/><path d="M352 402q48-20 99-4m-78 27q43-13 70-3" stroke="#b9d7d4" stroke-width="3" fill="none"/>
      <path d="M388 468q-35 32-93 24t-122 66" stroke="#a3c9c8" stroke-width="14" fill="none"/>
      <g class="mountain" transform="translate(300 40)"><path d="M-50 180 48 0 169 180Z" fill="#73939b"/><path d="M48 0 169 180 54 123Z" fill="#527780"/><path d="M48 0 88 60 63 52 49 72 24 47 4 71Z" fill="#f5f8ed"/></g>
      <g class="mountain" transform="translate(510 20)"><path d="M-26 184 74 0 214 184Z" fill="#88a2a6"/><path d="M74 0 214 184 79 132Z" fill="#5b7e89"/><path d="M74 0 119 57 93 48 73 72 49 53 31 72Z" fill="#f6f8ed"/></g>
      <g class="mountain" transform="translate(669 56)"><path d="M-10 160 72 0 180 160Z" fill="#8ba6a3"/><path d="M72 0 180 160 80 116Z" fill="#62878a"/><path d="M72 0 106 50 86 45 71 61 50 43 39 61Z" fill="#edf5e9"/></g>
      <g fill="#527e6c" opacity=".8">{#each [[62,345],[92,322],[120,373],[170,272],[196,240],[260,394],[289,356],[527,435],[560,476],[609,404],[804,395],[827,428],[693,508]] as tree}<path d={`M${tree[0]} ${tree[1]-30}l-12 24h7l-12 21h34l-12-21h7Z`}/>{/each}</g>
      <text class="map-water" x="359" y="436">BLUE WATER</text><text class="map-caption" x="44" y="49">THE ROCKIES</text><text class="map-subcaption" x="44" y="70">AN IMAGINED WALKING MAP</text>
      {#each expedition.trails as edge}{@const a=place(expedition,edge.a)}{@const b=place(expedition,edge.b)}<line x1={a.x} y1={a.y} x2={b.x} y2={b.y} class={`trail ${trailClass(edge.a,edge.b)}`}/>{/each}
      {#each expedition.nodes as n}<circle cx={n.x} cy={n.y} r="14" fill={game.visited.includes(n.id)?'#e9be6a':'#e9eee4'} stroke="#355d64" stroke-width="2"/>{/each}
      <g transform="translate(820 65)" fill="#345e66"><path d="M0-20-6 8 0 3 6 8Z"/><path d="M0 3v20" stroke="#345e66"/><text y="-27" text-anchor="middle" font-size="13">N</text></g>
     </svg>
     {#each expedition.nodes as n}{@const edge=paths.find(p=>p.to===n.id)}<button class="map-stop" class:current={game.at===n.id} class:visited={game.sketches.includes(n.id)} style={`left:${n.x/8.8}%;top:${n.y/5.6}%`} disabled={!edge||!!moveReason(expedition,game,n.id)} onclick={()=>go(n.id)} aria-label={`${n.name}${game.at===n.id?', you are here':edge?`, walk ${edge.time} daylight, ${edge.cost} energy`:', not connected from here'}`}><span class="pin">{n.id===game.at?'●':game.sketches.includes(n.id)?'✓':n.kind==='shelter'?'⌂':expedition.required.includes(n.id)?'✦':n.kind==='camp'?'⌂':'·'}</span><span class="pin-name">{n.name}</span></button>{/each}
    </div>
    </div><div class="legend"><span><i class="gold"></i>Your route</span><span><i></i>Connected trails</span><span>✦ Required sketch</span><span>⌂ Shelter / trailhead</span></div>
    <div class="journal"><span class="journal-mark">“</span><div><p class="eyebrow">NOTES TO SEND HOME</p><p role="status" aria-live="polite">{game.log}</p></div></div>
   </section>
   <aside class="trail-panel" aria-label="Trail choices and actions">
    {#if game.status==='won'}
     <div class="ending"><p class="eyebrow">BACK BEFORE SUNDOWN</p><div class="medal">{'◆'.repeat(stars(expedition,game))}</div><h2>A grand day<br><em>up country.</em></h2><p>Every required view sketched, and both boots back at the trailhead.</p><strong class="score">{score(expedition,game)}<small>TRAIL POINTS</small></strong><p>{used} daylight spent · {game.sketches.length} sketches</p>{#if selected<EXPEDITIONS.length-1}<button class="primary" onclick={()=>choose(selected+1)}>Next expedition</button>{:else}<p class="congratulations">The Rockies notebook is complete. Try another route for extra sketches and a higher score.</p>{/if}<button class="secondary" onclick={()=>choose(selected)}>Walk this route again</button></div>
    {:else if game.status==='lost'}
     <div class="ending"><p class="eyebrow">THE DAY HAS DRAWN IN</p><h2>Tomorrow<br><em>is another trail.</em></h2><p>You ran out of daylight before completing the round. Undo your last action to adjust the route, or start again.</p><button class="primary" onclick={undo} disabled={!history.length}>Undo last action</button><button class="secondary" onclick={()=>choose(selected)}>Try the expedition again</button></div>
    {:else}
     <p class="eyebrow">YOUR NEXT FOOTSTEPS</p><h2>Take a trail.</h2><p class="panel-intro">Climbing costs extra energy. Every trail shows its full cost before you walk.</p>
     <div class="route-list">{#each paths as edge}<button class="route" disabled={!!moveReason(expedition,game,edge.to)} onclick={()=>go(edge.to)} aria-label={`Walk to ${place(expedition,edge.to).name}, ${edge.time} daylight, ${edge.cost} energy`}><span><strong>{place(expedition,edge.to).name}</strong><small>{edge.name}</small></span><span class="route-cost"><b>{edge.time} daylight</b><b>{edge.cost} energy</b></span>{#if edge.ascent}<em>Climb {edge.ascent} elevation {edge.ascent===1?'band':'bands'}</em>{:else}<em>Level or downhill</em>{/if}{#if moveReason(expedition,game,edge.to)}<span class="blocked">{moveReason(expedition,game,edge.to)}</span>{/if}</button>{/each}</div>
     <div class="stop-actions"><h3>While you’re here</h3><button class="primary" disabled={!!sketchReason(expedition,game)} onclick={()=>commit(sketch(expedition,game))}>{game.sketches.includes(game.at)?'View already sketched':'Sketch this view'}<small>{current.stamp?'1 daylight · adds a sketch':'Find a marked lookout'}</small></button><button class="secondary" disabled={!!restReason(expedition,game)} onclick={()=>commit(rest(expedition,game))}>{shelterFree(expedition,game)?'Shelter break':'Take a tea break'}<small>1 daylight · +7 energy {shelterFree(expedition,game)?'· no ration used':'· 1 tea ration'}</small></button></div>
    {/if}
    <div class="tools"><button onclick={undo} disabled={!history.length}>Undo</button><button onclick={()=>choose(selected)}>Restart hike</button><button onclick={showHint} disabled={game.status!=='playing'}>Trail hint</button></div>{#if hint}<p class="hint" role="status">{hint}</p>{/if}
   </aside>
  </div>
  <section class="sketchbook" aria-label="Lookout sketchbook"><div><p class="eyebrow">BRING HOME THE VIEW</p><h2>Your mountain notebook.</h2><p>Collect the marked sketches and finish at the trailhead. Other views add bonus points.</p></div><div class="stamp-grid">{#each expedition.nodes.filter(n=>n.stamp) as n}<div class="stamp" class:collected={game.sketches.includes(n.id)}><svg viewBox="0 0 100 65" aria-hidden="true"><path d="M2 59 31 14 50 37 66 6 98 59Z" fill="currentColor" opacity=".65"/><path d="m31 14 9 12-8-4-7 3zm35-8 12 18-9-5-8 4-6-2z" fill="#edf1e8"/>{#if game.sketches.includes(n.id)}<circle cx="83" cy="14" r="12" fill="#d7a44a"/><path d="m77 14 4 4 8-9" stroke="#fff" fill="none" stroke-width="3"/>{/if}</svg><strong>{n.name}</strong><span>{expedition.required.includes(n.id)?'REQUIRED VIEW':'BONUS VIEW'}</span><small>{game.sketches.includes(n.id)?'In the notebook':'Still to sketch'}</small></div>{/each}</div></section>
  <details class="field-guide"><summary>The small print on the map</summary><p>Daylight is a game resource, not a clock. One action resolves immediately; there is no timer. Trails spend the listed daylight and energy, with uphill elevation adding to the cost. Sketches and breaks each spend one daylight. A break restores seven energy, up to twelve; the first break at a shelter uses no tea ration.</p><p>Reach the trailhead with every required sketch to win. Arrival on the last daylight point counts. Three badges reward finishing within {expedition.par} daylight on this expedition; extra views and leftover supplies add score. Undo is always available. Best badges stay in this browser; a reload starts a fresh hike.</p><p>These are fictional trail networks inspired by the Canadian Rockies in Alberta. Banff and Jasper are inland mountain destinations. This game does not show real trails, weather, closures, or hiking guidance. <a href="https://parks.canada.ca/pn-np/ab/banff/visit/promenadedesglaciers-icefieldsparkway" target="_blank" rel="noopener">Explore the real Banff–Jasper corridor with Parks Canada.</a></p></details>
 </main>
 <footer><span>FROM SALT AIR TO HIGH COUNTRY.</span><span>Original SVG artwork · Svelte + TypeScript</span><a href="https://funapps.ca">Back to FunApps</a></footer>
</div>
{#if modal}<div class="modal-backdrop"><div bind:this={dialog} class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1" onkeydown={modalKeys}><p class="eyebrow">A LITTLE WALK, A DIFFERENT HORIZON</p><h2 id="dialog-title">{modal==='intro'?'You can’t see the ocean from here.':'A good route begins with a look.'}</h2><p>You’ve come from the Maritimes with a sketchbook and a thermos. Explore four little mountain maps inspired by Banff and Jasper, then bring the views home.</p><ol><li><strong>Read the route.</strong> Click a connected map stop or a trail button. Uphill trails cost more energy.</li><li><strong>Keep a little in reserve.</strong> Daylight and energy are limited. Tea restores energy; a shelter’s first break saves a ration.</li><li><strong>Bring home the sketches.</strong> Sketch every required view, then return to the trailhead before daylight runs out.</li></ol><p class="modal-note">No timer. Mouse, touch or Tab + Enter. Undo any step. These are imagined walking maps, not real hiking routes.</p><button class="primary" onclick={()=>modal=null}>{modal==='intro'?'Pack the sketchbook':'Back to the trail'}</button></div></div>{/if}
